//! PostgreSQL SQL dialect.

use kernway_orm_core::{
    dialect::SqlDialect,
    entity::{ColumnDef, ColumnType},
};

/// PostgreSQL SQL dialect adapter.
///
/// Key differences from the default dialect:
/// - Placeholders are `$1`, `$2`, … (positional)
/// - A generated key is `GENERATED BY DEFAULT AS IDENTITY`
/// - `INSERT … RETURNING` is supported
/// - Identifiers are quoted with double quotes (same as standard SQL)
pub struct PostgresDialect;

impl SqlDialect for PostgresDialect {
    fn name(&self) -> &'static str {
        "postgres"
    }

    fn placeholder(&self, index: usize) -> String {
        format!("${}", index)
    }

    fn auto_increment_keyword(&self) -> &'static str {
        ""
    }

    fn supports_returning(&self) -> bool {
        true
    }

    /// A generated key is an identity column.
    fn column_ddl(&self, col: &ColumnDef) -> String {
        if col.primary_key && col.auto {
            return format!("{} GENERATED BY DEFAULT AS IDENTITY", self.col_type_ddl(&col.col_type));
        }
        self.col_type_ddl(&col.col_type).to_string()
    }

    fn lock_for_update_suffix(&self) -> &'static str {
        "FOR UPDATE"
    }

    fn col_type_ddl(&self, col_type: &ColumnType) -> &'static str {
        match col_type {
            ColumnType::Integer => "INTEGER",
            ColumnType::BigInt => "BIGINT",
            ColumnType::Boolean => "BOOLEAN",
            ColumnType::Float => "DOUBLE PRECISION",
            ColumnType::Text | ColumnType::Unknown => "TEXT",
            ColumnType::Timestamp => "TIMESTAMPTZ",
            ColumnType::Json => "JSONB",
            ColumnType::Binary => "BYTEA",
        }
    }
}
